/* Bubbles */
(function(){
  const c = document.getElementById('bub'), ctx = c.getContext('2d');
  let W, H, B = [];
  const PAL = [[141,213,212],[242,196,206],[245,240,232],[60,181,198],[90,181,180]];
  function resize() { W = c.width = innerWidth; H = c.height = innerHeight; }
  resize(); window.addEventListener('resize', resize);
  function mk(init) {
    const cl = PAL[Math.floor(Math.random()*PAL.length)];
    return { x: Math.random()*W, y: init ? Math.random()*H : H+60, r: 5+Math.random()*35, vx:(Math.random()-.5)*.45, vy:-(0.2+Math.random()*.55), a:0.06+Math.random()*.18, born: performance.now(), life:9000+Math.random()*14000, r:cl[0],g:cl[1],b:cl[2] };
  }
  /* rename to avoid shadowing */
  function mkB(init) {
    const cl = PAL[Math.floor(Math.random()*PAL.length)];
    const rad = 5+Math.random()*35;
    return { x: Math.random()*W, y: init ? Math.random()*H : H+60, rad, vx:(Math.random()-.5)*.45, vy:-(0.2+Math.random()*.55), a:0.06+Math.random()*.18, born: performance.now(), life:9000+Math.random()*14000, cr:cl[0],cg:cl[1],cb:cl[2] };
  }
  for(let i=0;i<40;i++) B.push(mkB(true));
  function frame(now) {
    ctx.clearRect(0,0,W,H);
    if(Math.random()<.02) B.push(mkB(false));
    B = B.filter(b => {
      const age = now - b.born;
      if(age > b.life) return false;
      const fade = age<600 ? age/600 : age>b.life-900 ? (b.life-age)/900 : 1;
      b.x+=b.vx; b.y+=b.vy;
      ctx.save();
      ctx.beginPath(); ctx.arc(b.x,b.y,b.rad,0,Math.PI*2);
      ctx.fillStyle = `rgba(${b.cr},${b.cg},${b.cb},${b.a*fade})`;
      ctx.fill();
      /* specular highlight */
      const g = ctx.createRadialGradient(b.x-b.rad*.3,b.y-b.rad*.35,b.rad*.04,b.x,b.y,b.rad);
      g.addColorStop(0,`rgba(255,255,255,${.55*fade})`);
      g.addColorStop(.5,`rgba(255,255,255,${.1*fade})`);
      g.addColorStop(1,`rgba(255,255,255,0)`);
      ctx.fillStyle = g; ctx.fill();
      /* thin edge */
      ctx.strokeStyle=`rgba(255,255,255,${.2*fade})`; ctx.lineWidth=.8; ctx.stroke();
      ctx.restore();
      return true;
    });
    requestAnimationFrame(frame);
  }
