}
.nav-links a:hover { color: var(--gris); }

/* Botón CTA: pastilla con relieve físico */
.nav-cta {
  background: linear-gradient(165deg, #4cc3d4 0%, #3CB5C6 45%, #2a9bab 100%);
  color: white !important;
  padding: 0.5rem 1.3rem;
