  font-size: 0.76rem !important;
  font-weight: 500 !important;
  box-shadow: 0 3px 12px rgba(60,181,198,0.45), inset 0 1px 0 rgba(255,255,255,0.4), inset 0 -1px 0 rgba(0,0,0,0.12);
  transition: all .2s;
  position: relative;
}
.nav-cta::before {
  content: '';
  position: absolute; inset: 0; border-radius: 2rem;
  background: linear-gradient(180deg, rgba(255,255,255,0.18) 0%, transparent 60%);
  pointer-events: none;
}
.nav-cta:hover { transform: translateY(-1px); box-shadow: 0 6px 20px rgba(60,181,198,0.5), inset 0 1px 0 rgba(255,255,255,0.4); }

.lang-sw { display:flex; gap:4px; }
.lang-sw button {
  background: none; border: 1px solid rgba(154,147,144,0.4);
  padding: 3px 8px; border-radius: 4px; font-family: var(--font-sans); font-size: 0.68rem; cursor: pointer; color: var(--gris-lt); transition: all .2s;
}
.lang-sw button.active { border-color: var(--accent); color: var(--accent); background: rgba(141,213,212,0.1); }

.hamburger { display:none; flex-direction:column; gap:5px; background:none; border:none; cursor:pointer; }
.hamburger span { display:block; width:22px; height:1.5px; background: var(--gris-mid); border-radius:2px; transition: all .3s; }

/* ===================================================
   HERO — Fondo profundo con luz
=================================================== */
#hero {
  min-height: 100vh;
