}

/* Tarjeta cita — con relieve de papel */
.hero-quote-card {
  display: inline-block;
  max-width: 580px;
  margin: 0 auto 3rem;
  padding: 1.8rem 2.2rem;
  text-align: left;
  border-radius: 16px;
  background: rgba(255,255,255,0.55);
