.btn-3d:hover { transform: translateY(-2px); box-shadow: 0 10px 30px rgba(60,181,198,0.5), 0 4px 10px rgba(60,181,198,0.3), inset 0 1px 0 rgba(255,255,255,0.4), inset 0 -2px 0 rgba(0,0,0,0.14); }
.btn-3d:active { transform: translateY(1px); box-shadow: var(--shadow-press), inset 0 1px 0 rgba(255,255,255,0.3); }

.btn-ghost {
