  margin-bottom: 1rem;
}
.sec-desc { font-size: 0.92rem; font-weight: 300; line-height: 1.75; color: var(--gris-lt); }
.sec-dark .sec-h2 { color: rgba(255,255,255,0.92); }
.sec-dark .sec-desc { color: rgba(255,255,255,0.5); }

/* ===================================================
   SERVICIOS — Cards con relieve de vidrio
=================================================== */
.serv-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(255px, 1fr));
  gap: 1.4rem;
  max-width: 1120px; margin: 0 auto;
}

.serv-card {
  position: relative;
  padding: 2rem 1.8rem;
  border-radius: 18px;
  background: rgba(255,255,255,0.62);
  border: 1px solid rgba(255,255,255,0.85);
  box-shadow:
    var(--shadow-soft),
    inset 0 1px 0 rgba(255,255,255,0.95),
    inset 0 -1px 0 rgba(0,0,0,0.04);
  backdrop-filter: blur(8px);
  transition: all .3s cubic-bezier(0.34, 1.56, 0.64, 1);
  overflow: hidden;
}
/* Reflejo luz en ángulo superior */
.serv-card::before {
  content: '';
  position: absolute; top: 0; left: 0; right: 60%;
  height: 50%;
  background: linear-gradient(135deg, rgba(255,255,255,0.35) 0%, transparent 100%);
  border-radius: 18px 0 0 0;
  pointer-events: none;
}
/* Acento de color inferior */
.serv-card::after {
  content: '';
  position: absolute; bottom: 0; left: 10%; right: 10%; height: 2px;
  background: linear-gradient(90deg, transparent, var(--turq), transparent);
