.serv-tag {
  display: inline-block; margin-top: 1rem;
  font-size: 0.62rem; font-weight: 500; letter-spacing: 0.12em; text-transform: uppercase;
  padding: 0.2rem 0.7rem; border-radius: 1rem;
  background: rgba(141,213,212,0.15);
  color: var(--turq-deep);
  border: 1px solid rgba(141,213,212,0.3);
}

/* ===================================================
   EQUIP — Cards de perfil con profundidad
=================================================== */
.equip-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 1.8rem; max-width: 1000px; margin: 0 auto;
}

.psic-card {
  text-align: center;
  padding: 2.5rem 1.5rem;
  border-radius: 20px;
  position: relative; overflow: hidden;
  background: var(--crema);
