  box-shadow: var(--shadow-soft), inset 0 1px 0 rgba(255,255,255,0.95);
  transition: all .3s;
}
.psic-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lift), inset 0 1px 0 rgba(255,255,255,0.95);
}
/* Degradado de color en la parte superior */
.psic-card-top {
  position: absolute; top:0; left:0; right:0; height:90px;
  border-radius: 20px 20px 0 0;
  opacity: 0.18;
}

.avatar-3d {
  width: 88px; height: 88px;
  border-radius: 50%;
  margin: 0 auto 1.2rem;
  position: relative; z-index: 1;
  display: flex; align-items: center; justify-content: center;
  font-size: 0; /* ocultar si no hay img */
  border: 3px solid rgba(255,255,255,0.95);
  box-shadow: 0 6px 20px rgba(0,0,0,0.14), inset 0 1px 0 rgba(255,255,255,0.8);
}
.avatar-3d-inner {
  width: 100%; height: 100%;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-serif); font-size: 1.8rem; font-weight: 300;
  color: rgba(255,255,255,0.95);
  /* Esfera 3D: degradado y sombra interna */
  background: linear-gradient(145deg, var(--c1) 0%, var(--c2) 100%);
