#audio-play{width:28px;height:28px;border-radius:50%;background:linear-gradient(145deg,#4cc3d4,#3CB5C6,#2d9faf);border:none;cursor:pointer;box-shadow:0 3px 10px rgba(60,181,198,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;transition:all .2s}
#audio-play:hover{transform:scale(1.1)}
#audio-play svg{width:11px;height:11px;fill:white}
.bars{display:flex;align-items:flex-end;gap:2px;height:13px}
.bars span{display:block;width:3px;background:var(--accent);border-radius:1px;animation:bar .7s ease-in-out infinite alternate}
.bars span:nth-child(1){height:35%;animation-duration:.9s}
.bars span:nth-child(2){height:100%;animation-duration:.65s;animation-delay:.1s}
.bars span:nth-child(3){height:60%;animation-duration:1.1s;animation-delay:.2s}
.bars span:nth-child(4){height:80%;animation-duration:.75s;animation-delay:.05s}
.bars.paused span{animation-play-state:paused}
@keyframes bar{from{transform:scaleY(0.25)}to{transform:scaleY(1)}}
.rev{opacity:0;transform:translateY(24px);transition:opacity .65s cubic-bezier(.4,0,.2,1),transform .65s cubic-bezier(.4,0,.2,1)}
.rev.in{opacity:1;transform:none}
.rev.d1{transition-delay:.1s}
.rev.d2{transition-delay:.2s}
.rev.d3{transition-delay:.3s}
.rev.d4{transition-delay:.4s}
@media (max-width:768px){
  nav{padding:0 1.2rem}
  .nav-links{display:none;flex-direction:column;position:fixed;top:68px;left:0;right:0;background:rgba(245,240,232,0.97);backdrop-filter:blur(20px);padding:2rem;gap:1.5rem;border-bottom:1px solid rgba(255,255,255,0.7);box-shadow:0 10px 30px rgba(0,0,0,0.1)}
  .nav-links.open{display:flex}
  .hamburger{display:flex}
  .entrev-wrap{grid-template-columns:1fr}
  .entrev-perfil{position:static}
  .contacte-grid{grid-template-columns:1fr}
  .foot-inner{grid-template-columns:1fr;gap:2rem}
}
</style>
</head>
