<section class="sec sec-alt">
  <div class="sec-hdr rev">
    <span class="sec-eyebrow">Diversitat</span>
    <h2 class="sec-h2">El teu idioma,<br>benvingut aquí</h2>
  </div>
  <div class="idiom-grid rev">
    <div class="idiom-pill"><span class="idiom-flag">🇪🇸</span> Español</div>
    <div class="idiom-pill"><span class="idiom-flag">🏴󠁥󠁳󠁣󠁴󠁿</span> Català</div>
    <div class="idiom-pill"><span class="idiom-flag">🇬🇧</span> English</div>
    <div class="idiom-pill"><span class="idiom-flag">🇫🇷</span> Français</div>
    <div class="idiom-pill"><span class="idiom-flag">🇩🇪</span> Deutsch</div>
    <div class="idiom-pill"><span class="idiom-flag">🇵🇹</span> Português</div>
    <div class="idiom-pill"><span class="idiom-flag">🇲🇦</span> Àrab darija</div>
    <div class="idiom-pill"><span class="idiom-flag">🇷🇴</span> Română</div>
