/* ===================================================
   FIXOS FLOTANTS
=================================================== */
/* Rellotge */
#clock {
  position: fixed; bottom: 22px; right: 22px; z-index: 90;
  background: rgba(245,240,232,0.78);
  backdrop-filter: blur(20px) saturate(150%);
  border: 1px solid rgba(255,255,255,0.7);
