  font-size: 0.78rem;
}
#clock-time { font-variant-numeric: tabular-nums; font-weight: 500; letter-spacing: 0.04em; }
#clock-tz { font-size: 0.62rem; color: var(--gris-lt); }

/* WhatsApp */
.wa {
  position: fixed; bottom: 88px; right: 22px; z-index: 90;
  width: 50px; height: 50px; border-radius: 50%;
  background: linear-gradient(145deg, #2de673, #25D366, #1aad52);
  box-shadow: 0 5px 20px rgba(37,211,102,0.5), inset 0 1px 0 rgba(255,255,255,0.3);
  display: flex; align-items: center; justify-content: center;
  text-decoration: none; transition: all .25s;
  animation: wa-pulse 3.5s ease infinite;
}
.wa svg { width:24px; height:24px; fill:white; }
.wa:hover { transform: scale(1.1) translateY(-2px); box-shadow: 0 10px 30px rgba(37,211,102,0.6); }
@keyframes wa-pulse { 0%,100% { box-shadow: 0 5px 20px rgba(37,211,102,0.5), inset 0 1px 0 rgba(255,255,255,0.3); } 50% { box-shadow: 0 5px 20px rgba(37,211,102,0.5), 0 0 0 8px rgba(37,211,102,0.12), inset 0 1px 0 rgba(255,255,255,0.3); } }

/* Audio */
#audio-widget {
  position: fixed; bottom: 22px; left: 22px; z-index: 90;
  background: rgba(245,240,232,0.78);
  backdrop-filter: blur(20px) saturate(150%);
  border: 1px solid rgba(255,255,255,0.7);
  box-shadow: var(--shadow-soft), inset 0 1px 0 rgba(255,255,255,0.9);
  border-radius: 12px; padding: 0.5rem 0.9rem;
  display: flex; align-items: center; gap: 0.7rem;
  font-size: 0.74rem; color: var(--gris-lt);
}
#audio-play {
  width: 28px; height: 28px; border-radius: 50%;
  background: linear-gradient(145deg, #4cc3d4, #3CB5C6, #2d9faf);
  border: none; cursor: pointer;
  box-shadow: 0 3px 10px rgba(60,181,198,0.4), inset 0 1px 0 rgba(255,255,255,0.35);
  display: flex; align-items: center; justify-content: center;
  transition: all .2s;
}
#audio-play:hover { transform: scale(1.1); }
#audio-play svg { width:11px; height:11px; fill:white; }
.bars { display:flex; align-items:flex-end; gap:2px; height:13px; }
.bars span { display:block; width:3px; background: var(--accent); border-radius:1px; animation: bar .7s ease-in-out infinite alternate; }
.bars span:nth-child(1) { height:35%; animation-duration:.9s; }
.bars span:nth-child(2) { height:100%; animation-duration:.65s; animation-delay:.1s; }
.bars span:nth-child(3) { height:60%; animation-duration:1.1s; animation-delay:.2s; }
.bars span:nth-child(4) { height:80%; animation-duration:.75s; animation-delay:.05s; }
.bars.paused span { animation-play-state: paused; }
@keyframes bar { from { transform: scaleY(0.25); } to { transform: scaleY(1); } }

/* ===================================================
   REVEAL
=================================================== */
.rev { opacity:0; transform: translateY(24px); transition: opacity .65s cubic-bezier(.4,0,.2,1), transform .65s cubic-bezier(.4,0,.2,1); }
.rev.in { opacity:1; transform:none; }
.rev.d1 { transition-delay:.1s; }
.rev.d2 { transition-delay:.2s; }
.rev.d3 { transition-delay:.3s; }
.rev.d4 { transition-delay:.4s; }

/* ===================================================
