<script>
/* Progress */
const pb = document.getElementById('prog');
window.addEventListener('scroll', () => { pb.style.transform = `scaleX(${window.scrollY / (document.documentElement.scrollHeight - innerHeight)})`; });

/* Hamburger */
document.getElementById('ham').addEventListener('click', () => document.getElementById('nl').classList.toggle('open'));
document.querySelectorAll('#nl a').forEach(a => a.addEventListener('click', () => document.getElementById('nl').classList.remove('open')));

/* Reveal */
const obs = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); obs.unobserve(e.target); } }), { threshold: 0.1 });
document.querySelectorAll('.rev').forEach(el => obs.observe(el));

/* Accordion */
function tog(btn) {
  const b = btn.nextElementSibling, o = btn.classList.contains('open');
  document.querySelectorAll('.acc-btn.open').forEach(x => { x.classList.remove('open'); x.nextElementSibling.classList.remove('open'); });
  if (!o) { btn.classList.add('open'); b.classList.add('open'); }
}

/* Clock */
function tick() {
  document.getElementById('clock-time').textContent = new Date().toLocaleTimeString('ca-ES', { timeZone:'Europe/Madrid', hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false });
}
tick(); setInterval(tick, 1000);

/* Audio */
let ap = false;
function aud() {
  const el = document.getElementById('a');
  ap = !ap;
  if (ap) { el.play().catch(()=>{}); } else { el.pause(); }
  document.getElementById('aico-play').style.display = ap ? 'none' : '';
  document.getElementById('aico-pause').style.display = ap ? '' : 'none';
  document.getElementById('abars').classList.toggle('paused', !ap);
}

/* Lang */
document.getElementById('bca').addEventListener('click', function() { this.classList.add('active'); document.getElementById('bes').classList.remove('active'); });
